export class Logger {
  error(msg: string, err?: unknown) {
    const event: LogEvent = {
      level: 'error',
      message: msg,
      timestamp: Date.now(),
      data: err instanceof Error ? { name: err.name, stack: err.stack } : undefined,
    };
    this.write(event);
    this.emit(event);
  }
}
